		return ErrLoopDetect
	}

	bf = bf.AddString(key)
	modifiedBloomFilter, err := bf.MarshalBinary()
	if err != nil {
		return err
	}

	meta.TraversalBloom = modifiedBloomFilter
	return nil
}

